head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS20800.xml';
scwin.vIsurCd, scwin.vBasIsuNm, scwin.vIsurNm;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.arrPar = new Array();
scwin.processGp; //등록 1, 수정 4, 삭제 5
scwin.vBtnStat_S, scwin.vBtnStat_M, scwin.vBtnStat_D;
scwin.btnStat = new Object();
scwin.vPopUpYn = '';
scwin.vPopDel = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명  	 : fn_SearchIsur
 * 설명       : 발행기관 리스트를 조회 한다.
 ***********************************************/
scwin.fn_SearchIsur = function() {
    var dsNm = 'BNS_ISUR_INFO';
    var qryId = 'lds.stf.bnscommon.select.listIsurCd';
    var param = '';
    if (scwin.vPopUpYn == '') {
        param = '&{P}V_ISUR_NM=' + $c.stf.getObjectValue(txb_IsurCd);
    } else {
        param = '&{P}V_ISUR_NM=' + scwin.vIsurCd;
    }
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsurList, dsNm, qryId, param);
    $c.cm.ShowWin(grd_IsurList);
};


/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(txb_IsurCd) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(txb_IsurCd);
};

/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_IsurCd)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_IsurCd, scwin.arrPar[0].ISUR_NM);
};


/********************************************** 
 * 함수명   : fn_list
 * 설명       : 채권기준명 리스트를 조회한다.
 ***********************************************/
scwin.fn_list = function() {
    var dsNm = 'BNS_ISU_BAS_NM';
    var qryId = 'lds.stf.bnscommon.select.listIsuBasNm';
    var param = '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    param += '&{P}V_POP_YN=' + 'N';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.bns.ShowWinArrPnlRight(pnl_Input, grd_List);
};


/********************************************** 
 * 함수명   : fn_BtnSetChange
 * 설명       : 버튼 셋(저장,수정,삭제) 변경
 * param	: num(1-저장만 enable / 2-저장만 disable)
 ***********************************************/
scwin.fn_BtnSetChange = function(num) {
    if (num == 1) {
        btn_Save.src = "../img/bns/btn_40.gif";
        btn_Mod.src = "../img/bns/btn_modify_nd.gif";
        btn_Del.src = "../img/bns/btn_delete_nd.gif";
        scwin.btnStat.Search = "en";
        scwin.btnStat.Reset = "en";
        scwin.btnStat.Save = "en";
        scwin.btnStat.Mod = "dis";
        scwin.btnStat.Del = "dis";
    } else if (num == 2) {
        btn_Save.src = "../img/bns/btn_40_d.gif";
        btn_Mod.src = "../img/bns/btn_modify_n.gif";
        btn_Del.src = "../img/bns/btn_delete_n.gif";
        scwin.btnStat.Search = "en";
        scwin.btnStat.Reset = "en";
        scwin.btnStat.Save = "dis";
        scwin.btnStat.Mod = "en";
        scwin.btnStat.Del = "en";
    }
    if (scwin.vPopUpYn != '') {
        btn_Search.src = "../img/bns/btn_select_nd.gif";
        btn_Reset.src = "../img/bns/btn_new_nd.gif";
        btn_Save.src = "../img/bns/btn_40_d.gif";
        btn_Mod.src = "../img/bns/btn_modify_n.gif";
        btn_Del.src = "../img/bns/btn_delete_n.gif";
        scwin.btnStat.Search = "dis";
        scwin.btnStat.Reset = "dis";
        scwin.btnStat.Save = "dis";
        scwin.btnStat.Mod = "en";
        scwin.btnStat.Del = "en";
    }
};



/********************************************** 
 * 함수명   : fn_ClearTextField
 * 설명       : 텍스트 필드를 초기화 한다.
 ***********************************************/
scwin.fn_ClearTextField = function() {
    $c.stf.setObjectValue(txb_BasIsuNm, '');
    $c.stf.setObjectValue(txb_BasIsuAbbrv, '');
    $c.stf.setObjectValue(txb_BasIsuEngNm, '');
    $c.stf.setObjectValue(txb_BasIsuEngAbbrv, '');
    dts_List.Reset();
    scwin.fn_BtnSetChange(1);
};


/********************************************** 
 * 함수명   : fn_GetStkIsuNm
 * 설명       : 주권종목명 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetStkIsuNm = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: scwin.vIsurCd,
        POP_CALL_YN: 'Y'
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명       : 필수 입력값 체크
 ***********************************************/
scwin.fn_InputCheck = function() {
    //등록, 수정, 삭제 시 체크
    if (scwin.vBasIsuNm == '') {
        $c.win.alert("[한글기준명]을 입력하십시오.");
        txb_BasIsuNm.focus();
        return false;
    }

    //자리수 체크
    if (!$c.stf.checkMaxLength(txb_BasIsuNm, 60, '한글기준명')) return false;
    if (!$c.stf.checkMaxLength(txb_BasIsuAbbrv, 20, '한글기준약명')) return false;
    var pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
    var str = $c.stf.getObjectValue(txb_BasIsuEngNm);
    for (var i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('영문기준명에 한글은 사용할 수 없습니다');
            txb_BasIsuEngNm.focus();
            return false;
        }
    }
    var str = $c.stf.getObjectValue(txb_BasIsuEngAbbrv);
    for (var i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('영문기준약명에 한글은 사용할 수 없습니다');
            txb_BasIsuEngAbbrv.focus();
            return false;
        }
    }

    //등록, 수정 시 체크
    if (scwin.processGp == '1' || scwin.processGp == '4') {
        if ($c.stf.getObjectValue(txb_BasIsuAbbrv) == '') {
            $c.win.alert("[한글기준약명]을 입력하십시오.");
            txb_BasIsuAbbrv.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_BasIsuEngNm) == '') {
            $c.win.alert("[영문기준명]을 입력하십시오.");
            txb_BasIsuEngNm.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_BasIsuEngAbbrv) == '') {
            $c.win.alert("[영문기준약명]을 입력하십시오.");
            txb_BasIsuEngAbbrv.focus();
            return false;
        }
    }

    //수정, 삭제 시 체크
    if (scwin.processGp == '4' || scwin.processGp == '5') {
        var processGpNm;
        if (scwin.processGp == '4') processGpNm = '수정';
        if (scwin.processGp == '5') processGpNm = '삭제';
        //기준종목명 동일 여부 체크
        if (scwin.vBasIsuNm != dts_List.getCellData(dts_List.getRowPosition(), "BAS_ISU_NM")) {
            $c.win.alert("한글기준명은 수정하실수 없습니다.");
            $c.stf.setObjectValue(txb_BasIsuNm, dts_List.getCellData(dts_List.getRowPosition(), "BAS_ISU_NM"));
            return false;
        }
    }
    return true;
};

/********************************************** 
 * 함수명   : fn_DuplCheck
 * 설명       : 등록 시, 중복 체크
 ***********************************************/
scwin.fn_DuplCheck = function() {
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if ($c.stf.getObjectValue(txb_BasIsuNm) == dts_List.getCellData(i, "BAS_ISU_NM")) {
            $c.win.alert("동일한 [한글기준명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuNm.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_BasIsuAbbrv) == dts_List.getCellData(i, "BAS_ISU_ABBRV")) {
            $c.win.alert("동일한 [한글기준약명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuAbbrv.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_BasIsuEngNm) == dts_List.getCellData(i, "BAS_ISU_ENG_NM")) {
            $c.win.alert("동일한 [영문기준명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuEngNm.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_BasIsuEngAbbrv) == dts_List.getCellData(i, "BAS_ISU_ENG_ABBRV")) {
            $c.win.alert("동일한 [영문기준약명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuEngAbbrv.focus();
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명		: fn_SetDataSet
 * 설명			: 텍스트 필드를 데이터셋에 설정
 ***********************************************/
scwin.fn_SetDataSet = function() {
    dts_SaveItem.insertRow();
    dts_SaveItem.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_SaveItem.setCellData(1, "BAS_ISU_NM", $c.stf.getObjectValue(txb_BasIsuNm));
    dts_SaveItem.setCellData(1, "BAS_ISU_ABBRV", $c.stf.getObjectValue(txb_BasIsuAbbrv));
    dts_SaveItem.setCellData(1, "BAS_ISU_ENG_NM", $c.stf.getObjectValue(txb_BasIsuEngNm));
    dts_SaveItem.setCellData(1, "BAS_ISU_ENG_ABBRV", $c.stf.getObjectValue(txb_BasIsuEngAbbrv));
};


/********************************************** 
 * 함수명   : fn_InsertModDel
 * 설명       : 등록 및 수정, 삭제를 처리한다.
 ***********************************************/
scwin.fn_InsertModDel = function() {
    scwin.vBasIsuNm = $c.stf.getObjectValue(txb_BasIsuNm);
    //필수입력값 체크
    if (scwin.fn_InputCheck() == false) return;
    var url;
    if (scwin.processGp == '1') {
        //중복체크
        if (scwin.fn_DuplCheck() == false) return;
        if (!confirm("한글기준명 " + scwin.vBasIsuNm + "으로 등록하시겠습니까?")) return;
        url = "/bns/ListBzAppl.do?method=createIsuBas";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    } else if (scwin.processGp == '4') {
        var output = "한글기준명 " + scwin.vBasIsuNm + "를 수정시겠습니까?";
        output += "\n" + "수정된 한글기준명은 수정일 이후부터 적용되니,";
        output += "\n" + "기 상장종목의 한글기준명 변경 시 별도로 조치하여야 합니다.";
        if (!confirm(output)) return;
        url = "/bns/ListBzAppl.do?method=updateIsuBas";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    } else if (scwin.processGp == '5') {
        if (!confirm("한글기준명 " + scwin.vBasIsuNm + "를 삭제하시겠습니까?")) return;
        url = "/bns/ListBzAppl.do?method=deleteIsuBas";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&ISUR_CD=" + scwin.vIsurCd;

    //if (dts_SaveItem.NameValue(1, "BAS_ISU_NM") != dts_List.NameValue(1, "BAS_ISU_NM")) {
    scwin.fn_SetDataSet();
    //}
    dts_SaveItem.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaveItem)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.vPopUpYn = scwin.arrPar[0].POP_CALL;
        scwin.vIsurCd = scwin.arrPar[0].ISUR_CD;
        $c.stf.setObjectValue(txb_IsurCd, scwin.arrPar[0].ISUR_NM);
        scwin.fn_SearchIsur();
    }
};
scwin.gform_onload = function() {
    //호출파라미터설정
    scwin.fn_SetParam();

    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(pnl_IsurSearch);
    $c.bns.BnsPanelToGroupBox(pnl_Input);

    //발행기관 검색 포커스
    if (scwin.vPopUpYn == '') $c.stf.setObjectValue(txb_IsurCd, "");
    txb_IsurCd.focus();
    scwin.vIsurCd = $c.stf.getObjectValue(txb_IsurCd);

    //가우스헤더 셋팅(입력항목)
    dts_SaveItem.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_ISU_BAS_NM";
    dts_SaveItem.Reset();
};
scwin.txb_IsurCd_onkeypress = function() {
    if (scwin.vPopUpYn != '') return;
    if (event.keyCode == 13) scwin.fn_SearchIsur();
};
scwin.img_IsurCdNm_onclick = function() {
    if (scwin.vPopUpYn != '') return;
    scwin.fn_ShowIsur(lbl_IsurNmCd);
};
scwin.btn_Search_onclick = function() {
    if (scwin.vPopUpYn != '') {
        if (scwin.btnStat.Search = "dis") return;
        return;
    }
    scwin.fn_SearchIsur();
};
scwin.dts_IsurList_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_IsurList_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    $c.cm.CloseWin(rowcount, grd_IsurList);
    if (scwin.vPopUpYn != '') {
        dts_IsurList.setRowPosition(1, 0);
        scwin.vIsurCd = dts_IsurList.getCellData(dts_IsurList.getRowPosition(), "ISUR_CD");
        scwin.fn_list();
    } else {
        dts_IsurList.setRowPosition(0, 0);
    }
};
scwin.grd_IsurList_OnClick = function(row) {
    scwin.vIsurCd = dts_IsurList.getCellData(dts_IsurList.getRowPosition(), "ISUR_CD");
    scwin.fn_list();
    scwin.fn_ClearTextField();
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    dts_List.setRowPosition(0, 0);
    $c.bns.CloseWinArrPnlRight(rowcount, pnl_Input, grd_List);
    scwin.fn_BtnSetChange(1);
    if (scwin.vPopUpYn == 'Y') {
        var vRow = $c.cp.getNameValueRow(dts_List, "BAS_ISU_NM", scwin.arrPar[0].BAS_ISU_NM);
        dts_List.setRowPosition(vRow, 0);
        if (scwin.vPopDel != 'Y') {
            $c.stf.setObjectValue(txb_BasIsuNm, scwin.arrPar[0].BAS_ISU_NM);
            $c.stf.setObjectValue(txb_BasIsuAbbrv, scwin.arrPar[0].BAS_ISU_ABBRV);
            $c.stf.setObjectValue(txb_BasIsuEngNm, scwin.arrPar[0].BAS_ISU_ENG_NM);
            $c.stf.setObjectValue(txb_BasIsuEngAbbrv, scwin.arrPar[0].BAS_ISU_ENG_ABBRV);
        } else {
            $c.stf.setObjectValue(txb_BasIsuNm, "");
            $c.stf.setObjectValue(txb_BasIsuAbbrv, "");
            $c.stf.setObjectValue(txb_BasIsuEngNm, "");
            $c.stf.setObjectValue(txb_BasIsuEngAbbrv, "");
        }
    }
};
scwin.grd_List_OnClick = function(row, colid) {
    if (dts_List.getTotalRow() != 0) {
        scwin.fn_BtnSetChange(2);
        $c.stf.setObjectValue(txb_BasIsuNm, dts_List.getCellData(row, "BAS_ISU_NM"));
        $c.stf.setObjectValue(txb_BasIsuAbbrv, dts_List.getCellData(row, "BAS_ISU_ABBRV"));
        $c.stf.setObjectValue(txb_BasIsuEngNm, dts_List.getCellData(row, "BAS_ISU_ENG_NM"));
        $c.stf.setObjectValue(txb_BasIsuEngAbbrv, dts_List.getCellData(row, "BAS_ISU_ENG_ABBRV"));
    } else {
        scwin.fn_ClearTextField();
    }
};
scwin.btn_Reset_onclick = function() {
    if (scwin.vPopUpYn != '') {
        if (scwin.btnStat.Reset = "dis") return;
        return;
    }
    scwin.fn_ClearTextField();
};
scwin.btn_Save_onclick = function() {
    scwin.processGp = '1';
    if (scwin.btnStat.Save == "dis") return;
    scwin.fn_InsertModDel();
};
scwin.btn_Mod_onclick = function() {
    scwin.processGp = '4';
    if (scwin.btnStat.Mod == "dis") return;
    scwin.fn_InsertModDel();
};
scwin.btn_Del_onclick = function() {
    scwin.processGp = '5';
    if (scwin.btnStat.Del == "dis") return;
    scwin.fn_InsertModDel();
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
        scwin.fn_ClearTextField();
    }
    if (scwin.processGp == '4') {
        if (scwin.vPopUpYn == '') {
            $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
            scwin.fn_ClearTextField();
        } else if (scwin.vPopUpYn != '') {
            //부모 창 전송 값 설정
            scwin.arrPar[0].MOD_YN = 'Y';
            scwin.fn_SetPar(scwin.arrPar);
        }
    }
    if (scwin.processGp == '5') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
        scwin.fn_ClearTextField();
        scwin.vPopDel = 'Y'; //필드 클리어하기 위한키
        if (scwin.vPopUpYn != '') {
            //부모 창 전송 값 설정
            scwin.arrPar[0].DEL_YN = 'Y';
            scwin.fn_SetPar(scwin.arrPar);
        }
    }
    dts_List.Reset();
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
    }
    if (scwin.processGp == '4') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    }
    if (scwin.processGp == '5') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    }
};
scwin.btn_Cfm_onclick = function() {
    if (scwin.vIsurCd == "") return;
    scwin.fn_GetPar = fn_GetStkIsuNm;
    $c.bns.fn_PopStkIsuSearch(lbl_IsurNmCd);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
